inp=[[2,1,1,1],[2,0,1,2],[2,1,0,1],[0,2,2,0]]
out=[[2,1,1,1,0,2,2,2],[2,0,1,2,2,1,0,1],[2,1,0,1,2,0,1,1],[0,2,2,0,0,1,2,1],[1,2,1,0,0,2,2,0],[1,1,0,2,1,0,1,2],[1,0,1,2,2,1,0,2],[2,2,2,0,1,1,1,2]]
def blk(r,c): return [row[c*4:c*4+4] for row in out[r*4:r*4+4]]
import itertools
B=[[blk(i,j) for j in range(2)] for i in range(2)]
for i in range(2):
  for j in range(2): print(i,j,B[i][j])
def rot(g,k):
  for _ in range(k): g=[list(r) for r in zip(*g[::-1])]
  return g
mir=lambda g:[r[::-1] for r in g]
flv=lambda g:g[::-1]
tf={'id':lambda g:g,'r90':lambda g:rot(g,1),'r180':lambda g:rot(g,2),'r270':lambda g:rot(g,3),'mh':mir,'mv':flv,'tr':lambda g:[list(r) for r in zip(*g)],'anti':lambda g:[list(r) for r in zip(*g)][::-1]}
for name,f in tf.items():
  if f(inp)==B[0][1]: print('TR matches',name)
  if f(inp)==B[1][0]: print('BL matches',name)
  if f(inp)==B[1][1]: print('BR matches',name)
# maybe blocks are combinations e.g. h-mirror of left block columns
for name,f in tf.items():
  for name2,f2 in tf.items():
    comp=lambda g,a=f,b=f2: a(b(g))
    try:
      if comp(inp)==B[0][1]: print('TR',name,'o',name2)
      if comp(inp)==B[1][0]: print('BL',name,'o',name2)
      if comp(inp)==B[1][1]: print('BR',name,'o',name2)
    except: pass
